    add.s32 %r24, %r24, %r25;
    add.s32 %r24, %r24, %r21;

    cvt.s64.s32 %rd10, %r24;
    mul.lo.s64 %rd10, %rd10, 4;
    add.s64 %rd11, %rd1, %rd10;
