    mul.lo.s64 %rd12, %rd12, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f3, [%rd13];

    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_CONTINUE:
